import './App.css';

function OrgName() {
  return (
    <input type="text" id="orgname" placeholder="Enter Organization Name"></input>
  );
}

function AdminName() {
  return (
    <input type="text" id="adminname" placeholder="Enter Administrator Name"></input>
  );
}

export default function MyApp() {
  return (
    <div>
  <div className="OrgNameGroup">
    <label id="orgnametext">Organization Name</label>
    <OrgName />
  </div>

  <div className="AdminNameGroup">
    <label id="adminnametext">Admin</label>
    <AdminName />
  </div>
</div>


  );
}
